package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import org.joml.Quaterniond;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class NativeNavigationLockTest {
    private static NativeSpaceNavigation.Candidate candidate(int id,double x,double y,double angle){return new NativeSpaceNavigation.Candidate(id,new NativeSpaceNavigation.Marker(x,y,false,0),angle);}
    @Test void coneIncludesBoundaryButNotBehindOrInvalid(){assertEquals(20,NativeSpaceNavigation.LOCK_CONE);assertEquals(1,NativeSpaceNavigation.choose(List.of(candidate(0,.5,.5,20.0001),candidate(1,.6,.5,20),candidate(2,.5,.5,180),candidate(3,.5,.5,Double.NaN)),800,400));assertEquals(-1,NativeSpaceNavigation.choose(List.of(),800,400));assertEquals(-1,NativeSpaceNavigation.choose(List.of(candidate(0,.5,.5,90)),800,400));}
    @Test void ringUsesPixelDistanceNotPointerOrFractionDistance(){assertEquals(1,NativeSpaceNavigation.choose(List.of(candidate(0,.55,.5,5),candidate(1,.5,.57,10)),800,400));assertEquals(0,NativeSpaceNavigation.choose(List.of(candidate(0,.5,.5,5),candidate(1,.5,.5,1)),800,400));}
    @Test void edgeMarkerCanWinWithinCone(){var edge=new NativeSpaceNavigation.Candidate(7,new NativeSpaceNavigation.Marker(.95,.5,true,0),19);assertEquals(7,NativeSpaceNavigation.choose(List.of(edge),800,400));}
    @Test void arrivalFormatsMinutesAndRoundsUp(){assertEquals("01:01",NativeSpaceNavigation.arrival(new NativeSpaceNavigation.Reading(120.1,2)));assertEquals("00:00",NativeSpaceNavigation.arrival(new NativeSpaceNavigation.Reading(-1,2)));assertEquals("100:00",NativeSpaceNavigation.arrival(new NativeSpaceNavigation.Reading(6000,1)));}
    @Test void arrivalDoesNotInventAnEtaWithoutClosing(){for(double speed:new double[]{0,-1,Double.NaN,Double.POSITIVE_INFINITY})assertEquals("—",NativeSpaceNavigation.arrival(new NativeSpaceNavigation.Reading(100,speed)));assertEquals("—",NativeSpaceNavigation.arrival(new NativeSpaceNavigation.Reading(Double.NaN,1)));}
    @Test void velocityChoosesLockedOrReferenceIncludingTheirOrbits(){var model=NativePlanetSystem.model();var frame=new NativeSpace.Frame(new Quaterniond().rotationXYZ(.3,.8,.2),NativeSpace.ORIGIN,0,GroundEphemeris.ZERO,new Point(2,3,4),900);assertEquals(0,NativeSpaceNavigation.velocity(model,frame,-1,900).sub(frame.drift()).length(),1e-12);var expected=frame.drift().add(model.at(0,900).velocity()).sub(model.at(1,900).velocity());assertEquals(expected,NativeSpaceNavigation.velocity(model,frame,1,900));assertEquals(NativeSpaceNavigation.velocity(model,frame,-1,900),NativeSpaceNavigation.velocity(model,frame,9999,900));assertEquals(0,expected.sub(NativeSpaceNavigation.velocity(model,frame.toward(1,model,900),1,900)).length(),1e-12);}
    @Test void velocityThresholdAndRetrograde(){assertNull(NativeSpaceNavigation.velocityMarker(new Point(0,0,-.049)));var front=NativeSpaceNavigation.velocityMarker(new Point(0,0,-.05));assertNotNull(front);assertFalse(front.retrograde());var back=NativeSpaceNavigation.velocityMarker(new Point(1,2,3));assertTrue(back.retrograde());assertEquals(new Point(-1,-2,-3),back.camera());}
    @Test void keyConsumedBeforeVanillaAndOnlyAtHelm()throws Exception{var root=java.nio.file.Path.of("src/main/java/dev/starfold");String mixin=java.nio.file.Files.readString(root.resolve("mixin/NativeNavigationKeyMixin.java")),client=java.nio.file.Files.readString(root.resolve("NativeSpaceNavigationClient.java"));assertTrue(mixin.contains("at=@At(\"HEAD\"),cancellable=true"));assertTrue(client.contains("(!lockKey.matches(key,scan)&&!nextKey.matches(key,scan))||NativeHelmClient.body()==null"));assertTrue(client.contains("action==org.lwjgl.glfw.GLFW.GLFW_PRESS&&visible()"));assertTrue(client.contains("body!=lockBody||mc.level!=lockLevel"));assertTrue(client.contains("transformDirection"));assertTrue(client.contains("sendToServer(new NativeSpacePackets.Target(planet))"));assertTrue(client.contains("if(locked==planet)return"));for(String language:new String[]{"en_us","zh_cn"})assertTrue(java.nio.file.Files.readString(java.nio.file.Path.of("src/main/resources/assets/starfold/lang/"+language+".json")).contains("key.starfold.lock_planet"));}
}
